// Copies the built Scramjet + controller files from node_modules into ./scramjet and ./controller
// (same layout as the official Scramjet demo). Run: npm install && npm run fetch-scramjet
//
// These two folders are NOT stored in the repo (see .gitignore): they are generated by this script,
// locally or by the GitHub Action. If the hub says it "couldn't load scramjet/scramjet.js", this step
// never ran (or failed) for the site you are looking at.
import { cpSync, rmSync, mkdirSync, existsSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const jobs = [
  { pkg: "@mercuryworkshop/scramjet",            to: "scramjet",   need: ["scramjet.js"] },
  { pkg: "@mercuryworkshop/scramjet-controller", to: "controller", need: ["controller.api.js", "controller.sw.js"] },
];

let failed = false;
for (const { pkg, to, need } of jobs) {
  const from = join(root, "node_modules", pkg, "dist"), dest = join(root, to);
  if (!existsSync(from)) {
    console.error(`ERROR: missing node_modules/${pkg}/dist - run "npm install" first (or the package layout changed).`);
    failed = true; continue;
  }
  rmSync(dest, { recursive: true, force: true }); mkdirSync(dest, { recursive: true });
  cpSync(from, dest, { recursive: true });
  const files = readdirSync(dest);
  console.log(`copied node_modules/${pkg}/dist -> ${to}/  (${files.length} entries)`);
  const missing = need.filter(f => !existsSync(join(dest, f)));
  if (missing.length) {
    console.error(`ERROR: ${to}/ is missing ${missing.join(", ")}. What the package shipped: ${files.join(", ") || "(empty)"}`);
    console.error(`       The package layout may have changed - index.html and sw.js expect these exact file names.`);
    failed = true;
  }
}
if (failed) process.exit(1);
console.log("OK: scramjet/scramjet.js, controller/controller.api.js and controller/controller.sw.js are in place.");
